#include "stdlib/lapack/base/dgttrf.h"

/**
* Computes an LU factorization of a real tridiagonal matrix.
*
* @param N       matrix order
* @param DL      subdiagonal elements, overwritten by multipliers
* @param D       diagonal elements, overwritten by the diagonal of U
* @param DU      superdiagonal elements, overwritten by the first superdiagonal of U
* @param DU2     output second superdiagonal of U
* @param IPIV    output zero-based pivot indices
* @return        zero on success, a zero-based zero-pivot index, or -1 if N is negative
*/
LAPACK_INT API_SUFFIX(c_dgttrf)( const LAPACK_INT N, double *DL, double *D, double *DU, double *DU2, LAPACK_INT *IPIV ) {
	return API_SUFFIX(c_dgttrf_ndarray)( N, DL, 1, 0, D, 1, 0, DU, 1, 0, DU2, 1, 0, IPIV, 1, 0 );
}
